!BPMStripline parameters
!device_type,     device_name,    asymX,        meanX,        sigmaX,       asymY,        meanY,        sigmaY
bpmstripline,	  BPM3C11,	  1.0e-3,	6.0,	      3.0e-3,	    1.0e-3,	  -1.5,		4.0e-3
bpmstripline,	  BPM3C12,	  1.0e-3,	6.0,	      3.0e-3,	    1.0e-3,	  -1.5,		4.0e-3
bpmstripline,	  BPM3C16,	  1.0e-3,	6.0,	      3.0e-3,	    1.0e-3,	  -1.5,		4.0e-3
bpmstripline,	  BPM3H02,	  1.0e-3,	6.0,	      3.0e-3,	    1.0e-3,	  -1.5,		4.0e-3
bpmstripline,	  BPM3H07A,	  1.0e-3,	6.0,	      3.0e-3,	    1.0e-3,	  -1.5,		4.0e-3
bpmstripline,	  BPM3H07B,	  1.0e-3,	6.0,	      3.0e-3,	    1.0e-3,	  -1.5,		4.0e-3
bpmstripline,	  BPM3H07C,	  1.0e-3,	6.0,	      3.0e-3,	    1.0e-3,	  -1.5,		4.0e-3

!BPMStripline resolution smearing:              xres          yres
bpmstripline,     BPM3C11,       resolution    0.0e-6,       0.0e-4
bpmstripline,     BPM3C12,       resolution    0.0e-6,       0.0e-4
bpmstripline,     BPM3C16,       resolution    0.0e-6,       0.0e-4
bpmstripline,     BPM3H02,       resolution    0.0e-6,       0.0e-4
bpmstripline,     BPM3H07A,      resolution    0.0e-6,       0.0e-4
bpmstripline,     BPM3H07B,      resolution    0.0e-6,       0.0e-4
bpmstripline,     BPM3H07C,      resolution    0.0e-6,       0.0e-4


!CombinedBPM parameters
!device_type,     device_name,                  asym,         mean,         sigma(jitter)
combinedbpm,      bpm_target,     xpos          0.0e-2,       0.0,          1.0e-3
combinedbpm,      bpm_target,     ypos          0.0e-2,       0.0,          1.0e-3
combinedbpm,      bpm_target,     xslope        0.0e-6,       0.0,          1.0e-4   ! was 1.0e-7 (rad); x1000 for mrad
combinedbpm,      bpm_target,     yslope        0.0e-6,       0.0,          1.0e-4   ! was 1.0e-7 (rad); x1000 for mrad

!  CombinedBPM drifts              	      amplitude (abs), phase shift (rad), frequency (Hz)
combinedbpm,      bpm_target,     xpos      drift     1.0e-2,      0.456,        39.0 !1
combinedbpm,      bpm_target,     ypos      drift     1.0e-2,      0.456,        47.0 !1
combinedbpm,      bpm_target,     xslope    drift     1.0e-3,      0.654,        49.0 !3  ! was 1.0e-6 (rad); x1000 for mrad
combinedbpm,      bpm_target,     yslope    drift     1.0e-3,      0.654,        43.0 !3  ! was 1.0e-6 (rad); x1000 for mrad

!BCM parameters
!device_type,     device_name,    asym,         mean,         sigma(jitter)
bcm,              BCM3H04A,       1.0e-1,       30.0,        0.02
bcm,              BCM3H04B,       4.0e-4,       30.0,        0.02

!BCM resolution smearing
bcm,              BCM3H04A,       resolution    0.0
bcm,              BCM3H04B,       resolution    0.0

!CombinedBCM parameters
!device_type,     device_name,    asym,         mean,         sigma(jitter)
combinedbcm,      bcm_target,     0.0,           30.0,        0.02 !0.02

!CombinedBCM drifts are defined as amplitude (abs unit),  phase shift (rad), frequency (Hz)
combinedbcm,      bcm_target,     drift         0.01,         0.0,          60.0 !0.01

!CombinedBCM beamtrip:                          Period,       Length,       Ramp
combinedbcm,      bcm_target,     beamtrip      50000.0,      5.0,          10.0

!EnergyCalculator parameters
!device type,     device name,    asym,         mean,         sigma(jitter)
energycalculator, target_energy,  0.0e-5,       0.0e-3,      1.0e-6 !1.0e-6

!EnergyCalculator drifts               amplitude (abs), phase shift (rad), frequency (Hz)
energycalculator, target_energy,  drift         1.0e-5,        0.0,          53.0 !1.0e-5